// LoadDataFile() tries /data/ first then /host/ so the same source
// works across all targets without compile-time flags.
//
// On host (Xtensa ISS, x86 unit tests), test data is embedded in headers.

#ifndef TENSORFLOW_LITE_MICRO_EXAMPLES_TFLM_TEST_UTIL_H_
#define TENSORFLOW_LITE_MICRO_EXAMPLES_TFLM_TEST_UTIL_H_

#include <cstdint>
#include <cstdio>
#include <cstdlib>

#if defined(__NuttX__)
#include <time.h>
#endif

namespace tflm_test_util {

#if defined(__NuttX__)

inline uint8_t* ReadFile(const char* path, size_t* out_size) {
  FILE* f = fopen(path, "rb");
  if (!f) return nullptr;
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz <= 0) {
    fclose(f);
    return nullptr;
  }
  uint8_t* buf = static_cast<uint8_t*>(malloc(static_cast<size_t>(sz)));
  if (!buf) {
    printf("ERROR: malloc(%ld) failed for %s\n", sz, path);
    fclose(f);
    return nullptr;
  }
  size_t rd = fread(buf, 1, static_cast<size_t>(sz), f);
  fclose(f);
  if (rd != static_cast<size_t>(sz)) {
    printf("ERROR: read %zu/%ld from %s\n", rd, sz, path);
    free(buf);
    return nullptr;
  }
  *out_size = static_cast<size_t>(sz);
  return buf;
}
inline uint8_t* LoadDataFile(const char* basename, size_t* out_size) {
  char path[256];
  snprintf(path, sizeof(path), "/data/%s", basename);
  uint8_t* buf = ReadFile(path, out_size);
  if (buf) {
    printf("Loaded %s from %s (%zu bytes)\n", basename, path, *out_size);
    return buf;
  }
  snprintf(path, sizeof(path), "/host/%s", basename);
  buf = ReadFile(path, out_size);
  if (buf) {
    printf("Loaded %s from %s (%zu bytes)\n", basename, path, *out_size);
    return buf;
  }
  printf("ERROR: cannot open %s under /data or /host\n", basename);
  return nullptr;
}

